package com.hms.dao.impl;
import com.hms.config.DatabaseConnection; import com.hms.dao.DoctorDao; import com.hms.model.Doctor; import java.sql.*; import java.util.*;
public class DoctorDaoImpl implements DoctorDao { public List<Doctor> findAll(String s)throws SQLException{List<Doctor> out=new ArrayList<>();String q="SELECT * FROM doctors WHERE active=TRUE AND (doctor_code LIKE ? OR full_name LIKE ? OR specialization LIKE ? OR department LIKE ?) ORDER BY full_name";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){String x="%"+(s==null?"":s)+"%";for(int i=1;i<=4;i++)p.setString(i,x);try(ResultSet r=p.executeQuery()){while(r.next())out.add(new Doctor(r.getInt("doctor_id"),r.getString("doctor_code"),r.getString("full_name"),r.getString("specialization"),r.getString("department"),r.getString("phone"),r.getString("available_days"),r.getTime("available_from").toLocalTime(),r.getTime("available_to").toLocalTime(),r.getBoolean("active")));}}return out;} }
